// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 balanceAmt, uint256 amount) public {
        balanceAmt = bound(balanceAmt, 0, type(uint256).max / 2);
        vm.assume(amount > balanceAmt);
        vm.deal(address(c), balanceAmt);
        vm.prank(c.owner());
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "over-sized withdraw must revert");
    }
}
